/// <summary>
/// Coordinates table selection, metadata collection, and relation exports.
/// The dialog supports choosing all tables or an exact single/multiple table selection,
/// then sends the collected rows to the Excel exporter, ERD exporter, or both.
/// </summary>
class TableRelationExporter extends RunBase
{
    DialogField             dialogExportAllTables;
    DialogField             dialogTableNames;
    DialogField             dialogIncludeViews;
    DialogField             dialogExportExcel;
    DialogField             dialogExportErd;
    SysLookupMultiSelectCtrl tableLookupCtrl;
    container               selectedTableNames;
    boolean                 exportAllTables;
    boolean                 includeViews;
    boolean                 doExcel;
    boolean                 doErd;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        exportAllTables,
        includeViews,
        doExcel,
        doErd,
        selectedTableNames
    #endmacro

}

Method.Source:
/// <summary>
/// Opens the parameter dialog and runs the operation when the user confirms it.
/// </summary>
/// <param name="_args">Arguments supplied by the menu item or class runner.</param>
[SuppressBPWarningAttribute('CARBPMethodNotReferenced', 'Invoked as the TableRelationExporter class entry point.')]
public static void main(Args _args)
{
    TableRelationExporter exporter = new TableRelationExporter();

    if (exporter.prompt())
    {
        exporter.runOperation();
    }
}

/// <summary>
/// Prevents the dialog-based operation from running in a separate session.
/// </summary>
/// <returns>False because the interactive lookup and dialog must remain in the caller session.</returns>
public boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Builds the exporter parameter dialog.
/// </summary>
/// <returns>The dialog containing table selection and output options.</returns>
public Object dialog()
{
    DialogRunbase dialog = super();

    dialog.caption('Table relation exporter');

    dialogExportAllTables = dialog.addField(extendedTypeStr(NoYesId), 'Export all tables');
    dialogExportAllTables.helpText('Yes exports every runtime table. No exports only the exact table names selected below.');
    dialogExportAllTables.value(NoYes::No);

    dialogTableNames = dialog.addField(extendedTypeStr(Description255), 'Tables to export');
    dialogTableNames.helpText('Use the lookup button to select one or more exact table names. Required when Export all tables is No.');

    dialogIncludeViews = dialog.addField(extendedTypeStr(NoYesId), 'Include views / data entities');
    dialogIncludeViews.helpText('No excludes views and data entities from the selected tables.');
    dialogIncludeViews.value(NoYes::No);

    dialogExportExcel = dialog.addField(extendedTypeStr(NoYesId), 'Export to Excel');
    dialogExportExcel.value(NoYes::Yes);

    dialogExportErd = dialog.addField(extendedTypeStr(NoYesId), 'Export ERD diagram (HTML)');
    dialogExportErd.value(NoYes::Yes);

    return dialog;
}

/// <summary>
/// Attaches a searchable multi-select lookup containing runtime table names to the dialog field.
/// </summary>
/// <param name="_dialog">Dialog run instance.</param>
public void dialogPostRun(DialogRunbase _dialog)
{
    FormRun             formRun;
    Query               query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    FormControl         tableNamesControl;

    super(_dialog);

    formRun = _dialog.dialogForm().formRun();

    if (!formRun)
    {
        throw error('Unable to initialize the table selection lookup.');
    }

    tableNamesControl = formRun.design().control(dialogTableNames.control().id());
    queryBuildDataSource = query.addDataSource(tableNum(SYSTABLEIDVIEW));
    queryBuildDataSource.fields().dynamic(false);
    queryBuildDataSource.addSelectionField(fieldNum(SYSTABLEIDVIEW, SqlName));
    queryBuildDataSource.addSortField(fieldNum(SYSTABLEIDVIEW, SqlName), SortOrder::Ascending);

    tableLookupCtrl = SysLookupMultiSelectCtrl::constructWithQuery(
        formRun,
        tableNamesControl,
        query,
        false,
        [tableNum(SYSTABLEIDVIEW), fieldNum(SYSTABLEIDVIEW, SqlName)]);
}

/// <summary>
/// Reads and validates the values entered in the dialog.
/// </summary>
/// <returns>True when dialog values were read successfully.</returns>
public boolean getFromDialog()
{
    boolean ret = super();

    if (!ret)
    {
        return false;
    }

    exportAllTables = dialogExportAllTables.value();
    includeViews    = dialogIncludeViews.value();
    doExcel         = dialogExportExcel.value();
    doErd           = dialogExportErd.value();
    selectedTableNames = tableLookupCtrl
        ? tableLookupCtrl.getSelectedFieldValues()
        : conNull();

    if (!exportAllTables && conLen(selectedTableNames) == 0)
    {
        return checkFailed('Select one or more tables, or set Export all tables to Yes.');
    }

    if (!doExcel && !doErd)
    {
        return checkFailed('Select Excel, ERD, or both export options.');
    }

    return true;
}

/// <summary>
/// Collects the selected table relations once and runs the requested exports.
/// </summary>
public void run()
{
    List                 relationRows = new List(Types::Container);
    Map                  typeCounts   = new Map(Types::String, Types::Integer);
    container            stats;
    int                  tableCount, stepCount, stepNo;
    int64                startTicks;
    str                  filterText, excelBase64, erdHtml;
    System.IO.MemoryStream excelStream, downloadStream;
    SysOperationProgress operationProgress;

    filterText = exportAllTables
        ? 'All tables'
        : strFmt('Selected tables (%1)', conLen(selectedTableNames));

    if (exportAllTables && doErd)
    {
        warning('ERD is not generated for all tables (too large). Select specific tables to generate an ERD.');
        doErd = false;
    }

    if (!doExcel && !doErd)
    {
        warning('Nothing selected to export.');
        return;
    }

    stepCount = 1 + (doExcel ? 1 : 0) + (doErd ? 1 : 0);

    operationProgress = new SysOperationProgress();
    operationProgress.setCaption('Table relation exporter');

    try
    {
        stepNo++;
        startTicks = WinAPIServer::getTickCount();

        stats = TableRelationDataCollector::collectRelationData(
            selectedTableNames,
            exportAllTables,
            includeViews,
            relationRows,
            typeCounts,
            operationProgress,
            strFmt('Step %1 of %2: Reading tables', stepNo, stepCount));
        tableCount = conPeek(stats, 1);

        info(strFmt('Step %1 of %2: read %3 tables (%4 non-system, %5 system), %6 relations, %7 rows in %8 s.',
            stepNo,
            stepCount,
            tableCount,
            conPeek(stats, 2),
            conPeek(stats, 3),
            conPeek(stats, 4),
            relationRows.elements(),
            (WinAPIServer::getTickCount() - startTicks) div 1000));

        if (tableCount == 0)
        {
            warning(strFmt('No tables found for: %1', filterText));
            return;
        }

        if (doExcel)
        {
            stepNo++;
            startTicks = WinAPIServer::getTickCount();

            excelBase64 = TableRelationExcelExporter::createExcelFile(
                relationRows,
                filterText,
                stats,
                typeCounts,
                operationProgress,
                strFmt('Step %1 of %2: Building Excel file', stepNo, stepCount));

            info(strFmt('Step %1 of %2: Excel workbook generated in %3 s.',
                stepNo,
                stepCount,
                (WinAPIServer::getTickCount() - startTicks) div 1000));
        }

        if (doErd)
        {
            stepNo++;

            erdHtml = TableRelationErdExporter::createErdHtml(
                relationRows,
                filterText,
                operationProgress,
                strFmt('Step %1 of %2: Building ERD diagram', stepNo, stepCount));
        }

        if (doExcel && doErd && erdHtml)
        {
            excelStream   = new System.IO.MemoryStream(System.Convert::FromBase64String(excelBase64));
            downloadStream = new System.IO.MemoryStream();

            using (System.IO.Compression.ZipArchive archive =
                new System.IO.Compression.ZipArchive(
                    downloadStream,
                    System.IO.Compression.ZipArchiveMode::Create,
                    true))
            {
                System.IO.Compression.ZipArchiveEntry excelEntry =
                    archive.CreateEntry('TableRelations.xlsx');
                System.IO.Stream excelEntryStream = excelEntry.Open();

                excelStream.CopyTo(excelEntryStream);
                excelEntryStream.Dispose();

                System.IO.Compression.ZipArchiveEntry erdEntry =
                    archive.CreateEntry('TableRelationsERD.html');
                System.IO.Stream erdEntryStream = erdEntry.Open();
                System.IO.StreamWriter erdWriter =
                    new System.IO.StreamWriter(erdEntryStream, System.Text.Encoding::UTF8);

                erdWriter.Write(erdHtml);
                erdWriter.Flush();
                erdWriter.Dispose();
            }

            downloadStream.Seek(0, System.IO.SeekOrigin::Begin);
            File::SendFileToUser(downloadStream, 'TableRelationExport.zip');
        }
        else if (doExcel)
        {
            downloadStream = new System.IO.MemoryStream(System.Convert::FromBase64String(excelBase64));
            downloadStream.Seek(0, System.IO.SeekOrigin::Begin);
            File::SendFileToUser(downloadStream, 'TableRelations.xlsx');
        }
        else if (erdHtml)
        {
            File::SendStringAsFileToUser(erdHtml, 'TableRelationsERD.html');
        }
    }
    finally
    {
        operationProgress.kill();
    }

    info(strFmt('Done. %1 tables (%2 non-system, %3 system), %4 relations, %5 rows.',
        tableCount,
        conPeek(stats, 2),
        conPeek(stats, 3),
        conPeek(stats, 4),
        relationRows.elements()));
}

/// <summary>
/// Packs parameter values for the RunBase framework.
/// </summary>
/// <returns>A container containing the current version and parameter values.</returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// Restores parameter values packed by the RunBase framework.
/// </summary>
/// <param name="_packedClass">Packed version and parameter values.</param>
/// <returns>True when the packed version is supported.</returns>
public boolean unpack(container _packedClass)
{
    int version = conPeek(_packedClass, 1);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            return true;
    }

    return false;
}
